import { create } from 'zustand';
import { persist } from 'zustand/middleware';

const mockUsers = [
  { id: '1', email: 'admin@example.com', password: 'admin123', name: 'Admin User' },
  { id: '2', email: 'user@example.com', password: 'user123', name: 'Demo User' },
];

export const useAuthStore = create(
  persist(
    (set) => ({
      user: null,
      isAuthenticated: false,
      isLoading: false,
      error: null,

      login: async (email, password) => {
        set({ isLoading: true, error: null });
        await new Promise((resolve) => setTimeout(resolve, 500));

        const user = mockUsers.find((candidate) => candidate.email === email && candidate.password === password);

        if (!user) {
          set({ error: 'Invalid email or password', isLoading: false });
          return { success: false, error: 'Invalid email or password' };
        }

        const { password: _ignoredPassword, ...userWithoutPassword } = user;
        set({ user: userWithoutPassword, isAuthenticated: true, isLoading: false });
        return { success: true };
      },

      register: async (email, password, name) => {
        set({ isLoading: true, error: null });
        await new Promise((resolve) => setTimeout(resolve, 500));

        const existingUser = mockUsers.find((candidate) => candidate.email === email);

        if (existingUser) {
          set({ error: 'Email already exists', isLoading: false });
          return { success: false, error: 'Email already exists' };
        }

        const newUser = {
          id: String(mockUsers.length + 1),
          email,
          password,
          name,
        };

        mockUsers.push(newUser);

        const { password: _ignoredPassword, ...userWithoutPassword } = newUser;
        set({ user: userWithoutPassword, isAuthenticated: true, isLoading: false });
        return { success: true };
      },

      logout: () => {
        set({ user: null, isAuthenticated: false, error: null });
      },

      clearError: () => {
        set({ error: null });
      },
    }),
    {
      name: 'auth-storage',
      partialize: (state) => ({
        user: state.user,
        isAuthenticated: state.isAuthenticated,
      }),
    }
  )
);